const getComparePairKind =
  (resolveValues: (row: CompareAnalyticsRow) => { primary: unknown; secondary: unknown }, isNumeric = false) =>
  (params: { data?: CompareAnalyticsRow }): MetricDeltaKind => {
    if (!params.data) {
      return MetricDeltaKind.Empty;
